using System;using System.Drawing;using System.Windows.Forms;
namespace GearLab {
 public sealed class NumberChrome:NativeWindow {
  readonly Control control;static readonly System.Runtime.CompilerServices.ConditionalWeakTable<Control,NumberChrome> windows=new System.Runtime.CompilerServices.ConditionalWeakTable<Control,NumberChrome>();
  NumberChrome(Control c){control=c;AssignHandle(c.Handle);c.HandleCreated+=(s,e)=>{if(Handle==IntPtr.Zero)AssignHandle(c.Handle);};c.HandleDestroyed+=(s,e)=>ReleaseHandle();}
  public static void Attach(NumericUpDown number){foreach(Control child in number.Controls)if(child.GetType().Name=="UpDownButtons"){NumberChrome existing;if(!windows.TryGetValue(child,out existing))windows.Add(child,new NumberChrome(child));}}
  protected override void WndProc(ref Message m){base.WndProc(ref m);if(m.Msg==15&&Handle!=IntPtr.Zero){using(var g=Graphics.FromHwnd(Handle))Draw(g);}else if((m.Msg==0x317||m.Msg==0x318)&&m.WParam!=IntPtr.Zero){using(var g=Graphics.FromHdc(m.WParam))Draw(g);}}
  void Draw(Graphics g){var r=control.ClientRectangle;g.Clear(UiPalette.Get("Field"));int half=r.Height/2;using(var p=new Pen(UiPalette.Get("Border"))){g.DrawLine(p,0,0,0,r.Height);g.DrawLine(p,0,half,r.Width,half);}using(var font=new Font("Segoe UI",7.5f)){TextRenderer.DrawText(g,"+",font,new Rectangle(0,0,r.Width,half),UiPalette.Get(control.Enabled?"Text":"Muted"),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);TextRenderer.DrawText(g,"−",font,new Rectangle(0,half,r.Width,r.Height-half),UiPalette.Get(control.Enabled?"Text":"Muted"),TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.NoPadding);}}
 }
 public sealed class EditorComboBox:ComboBox {
  public EditorComboBox(){FlatStyle=FlatStyle.Flat;DrawMode=DrawMode.OwnerDrawFixed;ItemHeight=24;IntegralHeight=false;DropDownHeight=260;}
  protected override void OnDrawItem(DrawItemEventArgs e){if(e.Index<0||e.Index>=Items.Count)return;bool selected=(e.State&DrawItemState.Selected)!=0;using(var b=new SolidBrush(UiPalette.Get(selected?"Selection":"Field")))e.Graphics.FillRectangle(b,e.Bounds);var text=new Rectangle(e.Bounds.X+8,e.Bounds.Y,Math.Max(0,e.Bounds.Width-12),e.Bounds.Height);TextRenderer.DrawText(e.Graphics,I18n.T(GetItemText(Items[e.Index])),Font,text,UiPalette.Get(Enabled?"Text":"Muted"),TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);}
  protected override void WndProc(ref Message m){base.WndProc(ref m);if(DropDownStyle!=ComboBoxStyle.DropDownList||!IsHandleCreated)return;if(m.Msg==15){using(var g=Graphics.FromHwnd(Handle))DrawChrome(g);}else if((m.Msg==0x317||m.Msg==0x318)&&m.WParam!=IntPtr.Zero){using(var g=Graphics.FromHdc(m.WParam))DrawChrome(g);}}
  void DrawChrome(Graphics g){var r=ClientRectangle;if(r.Width<3||r.Height<3)return;g.Clear(UiPalette.Get("Field"));using(var pen=new Pen(UiPalette.Get(Focused?"Accent":"Border")))g.DrawRectangle(pen,0,0,r.Width-1,r.Height-1);string text=SelectedIndex>=0?GetItemText(SelectedItem):Text;TextRenderer.DrawText(g,I18n.T(text),Font,new Rectangle(9,0,Math.Max(0,r.Width-38),r.Height),UiPalette.Get(Enabled?"Text":"Muted"),TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.NoPrefix);int x=r.Right-16,y=r.Height/2;using(var pen=new Pen(UiPalette.Get(Enabled?"Text":"Muted"),1.4f)){g.DrawLine(pen,x-4,y-2,x,y+2);g.DrawLine(pen,x,y+2,x+4,y-2);}}
 }
 public sealed class PlaybackControl:FlowLayoutPanel {
  readonly SafeNumber speed=new SafeNumber();readonly Label caption=new Label();bool syncing;
  public PlaybackControl(){AutoSize=true;WrapContents=false;Margin=new Padding(8,0,0,0);Height=32;caption.Text="Скорость ×";caption.AutoSize=true;caption.Padding=new Padding(0,7,4,0);speed.Minimum=.01m;speed.Maximum=10;speed.DecimalPlaces=2;speed.Increment=.05m;speed.Width=112;speed.AccessibleName="Скорость анимации ×";speed.Margin=new Padding(0,3,0,0);Controls.Add(caption);Controls.Add(speed);speed.ValueChanged+=(s,e)=>{if(syncing)return;try{AppSettings.SetAnimationSpeed((double)speed.Value);}catch(Exception ex){UiMessage.Show(this,ex.Message);Sync();}};speed.Leave+=(s,e)=>{decimal value;if(!speed.TryRead(out value)){Sync();return;}if(!syncing&&Math.Abs((double)value-AppSettings.Current.AnimationScale)>1e-9)try{AppSettings.SetAnimationSpeed((double)value);}catch(Exception ex){UiMessage.Show(this,ex.Message);Sync();}};AppSettings.Changed+=Sync;Disposed+=(s,e)=>AppSettings.Changed-=Sync;Sync();}
  void Sync(){if(IsDisposed)return;syncing=true;try{speed.Commit((decimal)AppSettings.Current.AnimationScale);}finally{syncing=false;}}
  internal SafeNumber SpeedField{get{return speed;}}
 }
}
